table ip filter 	# Filter table for input, output and forward rules
chain input {
	type nat hook src nat priority 0; # nat traffic to itself gets through
	ip saddr 10.1.0.0/24 ctstate new tcp dport 3389 reject;
	ip saddr 10.1.0.0/24 ctstate new tcp dport 22 reject;
}

chain output {
	type filter hook output priority 0; # outgoing traffic gets through
	ip saddr 172.16.20.100 ip dport 80 tcp flags syn,ack accept; # Allow web server traffic from loadbalancer
	"drop" # default policy for any unknown traffic is to drop in chain output
}

chain forward {
	type filter hook forwarded priority 50;
	iif "eth0" # DMZ
		ip proto {tcp} dport 53 accept;   # DNS Server (DNS port 53)
		ip saddr 172.16.20.100 ip proto tcp dport 80 accept; # Allow web server traffic from loadbalancer

	iif "eth1"  
	 ip saddr 10.0.0.0/16 ip protocol tcp flags syn,ack to 4.4.4.4 port 53 ctstate NEW reject;

	iif "wan0"
	 # Allow outgoing traffic for clients on the internal network only from application proxy
		ip saddr 10.0.0.0/16 ip proto {icmp6} from any accept; 
		if (iif "eth1") then { # Only allow internet bound traffic to go through 
			iif 10.1.0.0/24 # Management Network
				ip saddr any ip dport 3389 tcp flags syn,ack accept;  
				ip saddr any ip dport 22	 tcp flags syn,ack accept;
