		}

	iif "eth1" 
	   # Allow internal clients to access all DMZ servers directly except Application Proxy.
	   	ip saddr any ip proto {tcp,udp} dport 80 accept;
		if(ip host 172.16.20.10 or
		   ip host 172.16.20.11) then {
			iif 10.0.0.0/16 # Allow incoming traffic directly from the load balancer 
				ip saddr any iif "eth0" proto tcp dport {3389,22} accept;
		}
	if (iif 172.16.20.50) then {
	    ip dscp cs6 accept   
